auto K_TILE_MAX = size<2>(tAgA);   // number of k-tiles
for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
  copy(tAgA(_,_,k_tile), tAsA);     // gmem to smem, tA pattern
  copy(tBgB(_,_,k_tile), tBsB);
  cp_async_fence();
  cp_async_wait<0>();
  __syncthreads();                  // tile is in smem
  gemm(tCsA, tCsB, tCrC);           // smem to regs, tC pattern
